const express = require('express');
const crypto = require('crypto');
const app = express();

const SECRET_KEY = crypto.randomBytes(32);
const sessions = new Map();

// User store: passwords are stored as scrypt hashes (salt:hash), never plaintext.
// In production these would come from a database / secrets manager, not the source.
function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64);
}

function makeUserRecord(role, plaintext) {
  const salt = crypto.randomBytes(16);
  const hash = hashPassword(plaintext, salt);
  return { role, salt, hash };
}

// Credentials seeded at startup (replace with real secret store).
// Using env vars with fallbacks generated at runtime so nothing is hardcoded.
const USERS = {
  admin: makeUserRecord('admin', process.env.ADMIN_PASSWORD || crypto.randomBytes(24).toString('hex')),
  user: makeUserRecord('user', process.env.USER_PASSWORD || crypto.randomBytes(24).toString('hex'))
};

function verifyPassword(record, password) {
  if (!record) return false;
  const candidate = hashPassword(password, record.salt);
  // Constant-time comparison of derived hashes
  if (candidate.length !== record.hash.length) return false;
  return crypto.timingSafeEqual(candidate, record.hash);
}

// Utility: compute HMAC for session token
function computeMAC(payload, key) {
  const hmac = crypto.createHmac('sha256', key);
  hmac.update(payload);
  return hmac.digest();
}

// Utility: constant-time comparison to prevent timing attacks
function safeCompare(a, b) {
  if (!Buffer.isBuffer(a)) a = Buffer.from(a);
  if (!Buffer.isBuffer(b)) b = Buffer.from(b);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

// Parse a session token: format is base64(payload).base64(signature)
function parseToken(token) {
  const parts = token.split('.');
  if (parts.length !== 2) return null;

  const payloadB64 = parts[0];
  const signatureB64 = parts[1];

  const payload = Buffer.from(payloadB64, 'base64');
  const signature = Buffer.from(signatureB64, 'base64');

  return { payload, signature, payloadB64 };
}

// Verify token signature
function verifyToken(token) {
  const parsed = parseToken(token);
  if (!parsed) return null;

  const { payload, signature, payloadB64 } = parsed;

  // Compute expected signature
  const expectedSig = computeMAC(payloadB64, SECRET_KEY);

  // Verify signature matches exactly
  if (!safeCompare(signature, expectedSig)) {
    return null;
  }

  try {
    return JSON.parse(payload.toString('utf8'));
  } catch (e) {
    return null;
  }
}

// Create a signed token
function createToken(data) {
  const payloadB64 = Buffer.from(JSON.stringify(data)).toString('base64');
  const signature = computeMAC(payloadB64, SECRET_KEY);
  return `${payloadB64}.${signature.toString('base64')}`;
}

app.use(express.json());

app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || typeof username !== 'string' || username.length > 64) {
    return res.status(400).json({ error: 'Invalid username' });
  }
  if (!password || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid password' });
  }

  // Look up user record and verify password against stored hash (constant-time).
  const record = USERS[username];
  if (record && verifyPassword(record, password)) {
    const token = createToken({ username, role: record.role, iat: Date.now() });
    sessions.set(username, true);
    return res.json({ token });
  }

  res.status(401).json({ error: 'Invalid credentials' });
});

app.get('/api/profile', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }

  const token = authHeader.slice(7);
  const data = verifyToken(token);

  if (!data) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  res.json({ user: data });
});

app.get('/api/admin', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }

  const token = authHeader.slice(7);
  const data = verifyToken(token);

  if (!data || data.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json({ secrets: 'Top secret admin data', users: Array.from(sessions.keys()) });
});

module.exports = app;
